package com.example.orchestrator;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.time.*; import java.util.*; import java.util.concurrent.*;
@RestController @RequestMapping("/api/workflows") public class WorkflowController {
 enum Status {PENDING,RUNNING,WAITING_APPROVAL,SUCCEEDED,FAILED,REJECTED,SAFE_STOP}
 static class Task {String id,name;List<String> deps;Status status=Status.PENDING;int attempts;String output="";Task(String i,String n,String...d){id=i;name=n;deps=List.of(d);}}
 static class Run {String id,scenario,requirement;Status status=Status.RUNNING;Instant created=Instant.now();int retries=0,rollbacks=0;Map<String,Task> tasks=new LinkedHashMap<>();List<Map<String,Object>> audit=new CopyOnWriteArrayList<>();Run(String scenario,String req){id=UUID.randomUUID().toString();this.scenario=scenario;requirement=req;}}
 private final Map<String,Run> runs=new ConcurrentHashMap<>();
 public record StartRequest(String scenario,String requirement){} public record ApprovalRequest(boolean approved,String comment){}
 @PostMapping public ResponseEntity<?> start(@RequestBody StartRequest req){String sc=req.scenario()==null?"greenfield":req.scenario().toLowerCase(Locale.ROOT);if(!Set.of("greenfield","brownfield","ambiguous").contains(sc))return ResponseEntity.badRequest().body(Map.of("error","scenario must be greenfield, brownfield, or ambiguous"));if(req.requirement()==null||req.requirement().isBlank())return ResponseEntity.badRequest().body(Map.of("error","requirement is required"));Run r=new Run(sc,req.requirement());r.tasks.put("understand",new Task("understand","Normalize requirement"));r.tasks.put("design",new Task("design","Architecture and risk review","understand"));r.tasks.put("implementation",new Task("implementation","Implementation plan","design"));r.tasks.put("tests",new Task("tests","Test plan and validation","implementation"));r.tasks.put("docs",new Task("docs","Documentation","design"));r.tasks.put("release",new Task("release","Release readiness approval","tests","docs"));runs.put(r.id,r);executeReady(r);return ResponseEntity.accepted().body(view(r));}
 private void executeReady(Run r){boolean changed=true;while(changed){changed=false;for(Task t:r.tasks.values()){if(t.status!=Status.PENDING)continue;if(!t.deps.stream().allMatch(d->r.tasks.get(d).status==Status.SUCCEEDED))continue;if(t.id.equals("release")){t.status=Status.WAITING_APPROVAL;r.status=Status.WAITING_APPROVAL;t.output="Human approval required before release";audit(r,"GATE","Release paused for human approval");changed=true;continue;}t.status=Status.RUNNING;t.attempts++;try{t.output=executeTask(r,t);t.status=Status.SUCCEEDED;audit(r,"TASK_SUCCEEDED",t.id+": "+t.output);}catch(Exception e){if(t.attempts<2){r.retries++;t.status=Status.PENDING;audit(r,"RETRY",t.id+" retry scheduled");}else{t.status=Status.FAILED;r.status=Status.SAFE_STOP;audit(r,"SAFE_STOP","Task failed; no release action taken");return;}}changed=true;}}if(r.status==Status.RUNNING&&r.tasks.values().stream().allMatch(t->t.status==Status.SUCCEEDED))r.status=Status.SUCCEEDED;}
 private String executeTask(Run r,Task t){String req=r.requirement.toLowerCase(Locale.ROOT);return switch(t.id){case "understand"->"Requirement captured; scenario="+r.scenario+"; assumption: use REST APIs and deterministic validation";case "design"->"Service boundaries, API contracts, data model, security and failure modes recorded";case "implementation"->"Implementation tasks decomposed; no unreviewed source-code mutation performed";case "tests"->"Validation plan: unit, API integration, invalid input, expiry, retry and safe-stop checks";case "docs"->"Setup, architecture, assumptions, limitations and operational runbook prepared";default->"completed";};}
 private void audit(Run r,String type,String message){r.audit.add(Map.of("at",Instant.now().toString(),"type",type,"message",message));}
 @GetMapping("/{id}") public ResponseEntity<?> get(@PathVariable String id){Run r=runs.get(id);return r==null?ResponseEntity.notFound().build():ResponseEntity.ok(view(r));}
 @PostMapping("/{id}/approval") public ResponseEntity<?> approve(@PathVariable String id,@RequestBody ApprovalRequest a){Run r=runs.get(id);if(r==null)return ResponseEntity.notFound().build();Task t=r.tasks.get("release");if(t.status!=Status.WAITING_APPROVAL)return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","workflow is not waiting for approval"));if(!a.approved()){t.status=Status.REJECTED;r.status=Status.REJECTED;t.output="Rejected by human reviewer: "+(a.comment()==null?"no comment":a.comment());audit(r,"APPROVAL_REJECTED",t.output);}else{t.status=Status.SUCCEEDED;t.output="Approved by human reviewer: "+(a.comment()==null?"approved":a.comment());r.status=Status.SUCCEEDED;audit(r,"APPROVAL_GRANTED",t.output);}return ResponseEntity.ok(view(r));}
 @PostMapping("/{id}/safe-stop") public ResponseEntity<?> safeStop(@PathVariable String id){Run r=runs.get(id);if(r==null)return ResponseEntity.notFound().build();r.status=Status.SAFE_STOP;audit(r,"SAFE_STOP","Manually stopped by operator");return ResponseEntity.ok(view(r));}
 @GetMapping("/{id}/metrics") public ResponseEntity<?> metrics(@PathVariable String id){Run r=runs.get(id);if(r==null)return ResponseEntity.notFound().build();long latency=Duration.between(r.created,Instant.now()).toMillis();return ResponseEntity.ok(Map.of("status",r.status,"retryCount",r.retries,"rollbackCount",r.rollbacks,"endToEndLatencyMs",latency,"successRate",r.tasks.values().stream().filter(t->t.status==Status.SUCCEEDED).count()/(double)r.tasks.size()));}
 private Map<String,Object> view(Run r){Map<String,Object> ts=new LinkedHashMap<>();r.tasks.forEach((k,t)->ts.put(k,Map.of("name",t.name,"dependencies",t.deps,"status",t.status,"attempts",t.attempts,"output",t.output)));return Map.of("id",r.id,"scenario",r.scenario,"requirement",r.requirement,"status",r.status,"createdAt",r.created.toString(),"tasks",ts,"audit",r.audit);}
}
